using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: discriminator property renamed "$type".
            // Existing 500K docs use "Discriminator" — keep the old name so EF can
            // still read them and direct SQL queries (WHERE c.Discriminator = …) keep
            // working without a backfill migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: id values no longer include the
            // discriminator prefix.  New default would be "123"; existing docs
            // store "Product|123".  Preserve the EF 8 format so point-reads
            // against the existing container succeed.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<IdWithDiscriminatorValueGenerator>();
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 breaking change #3: sync I/O over async is no longer
        // allowed by default.  If you still need .ToList() etc. while you
        // migrate call-sites, uncomment the line below.  Prefer async APIs.
        // configurationBuilder.Conventions.Add(
        //     _ => new SyncIoConvention());
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; } = null!;
}

/// <summary>
/// Reproduces the EF Core 8 "Discriminator|Key" id format so existing
/// documents remain addressable.
/// </summary>
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class IdWithDiscriminatorValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var discriminator = entry.Metadata.GetDiscriminatorValue()?.ToString() ?? entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue;
        return $"{discriminator}|{key}";
    }
}

